"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["50187"],{4135(e){e.exports=JSON.parse('{"id":"V4-222","slug":"synthetic-identity-fraud","term":"Synthetic Identity Fraud","also_known_as":[],"difficulty":"Advanced","definition":"Synthetic identity fraud is a type of fraud in which criminals create a new, fake identity by combining real and invented personal information, such as a real identification number with a made-up name and date of birth, to open accounts and obtain credit.","explanation":["Unlike traditional identity theft, which uses a real person\u2019s full identity, synthetic identity fraud creates an identity that does not belong to any single real person. This makes it harder to detect, because there is no victim who notices unfamiliar accounts.","Fraudsters often build up the synthetic identity\u2019s credit history over time. They might apply for credit, be rejected at first, then gradually obtain small credit lines, make payments on time and increase their limits. Once the identity has a strong credit profile, they borrow as much as possible and disappear, a practice called busting out.","For example, a fraudster might use a stolen child\u2019s Social Security number, which is unlikely to be monitored, with a fake name to open credit cards and loans in the United States.","Synthetic identity fraud is considered one of the fastest-growing types of financial crime, especially in the United States. Lenders combat it using data analysis, identity verification services, document checks and checks against government databases. Generative AI may make creating convincing fake identity documents easier."],"note":"","total":1725,"prev":{"slug":"synergy","term":"Synergy"},"next":{"slug":"systematic-investment-plan","term":"Systematic Investment Plan (SIP)"}}')}}]);